def get_task_requirements(ctx):
    reqs = []
    task = ctx.task
    if hasattr(task, 'required_color') and task.required_color:
        reqs.append(('color', task.required_color))
    if hasattr(task, 'required_size') and task.required_size:
        reqs.append(('size', task.required_size))
    if hasattr(task, 'required_material') and task.required_material:
        reqs.append(('material', task.required_material))
    return reqs

def find_matching_option(clickables, req_type, req_value):
    if not clickables:
        return None
    req_lower = req_value.lower()
    for opt in clickables:
        opt_lower = opt.lower()
        if req_type == 'size':
            if req_lower in opt_lower or opt_lower in req_lower:
                return opt
        elif req_type == 'color':
            words = req_lower.split()
            match_count = sum(1 for w in words if w in opt_lower and len(w) > 2)
            if match_count >= 1:
                return opt
        elif req_type == 'material':
            if req_lower in opt_lower or opt_lower in req_lower:
                return opt
    return None

def hook(ctx, nb):
    action = ctx.action
    if not action or action.value_normalized != 'buy now':
        return None
    state = ctx.state
    if state.page_type != 'product_detail':
        return None
    if not ctx.predicates.required_options_unselected:
        return None
    reqs = get_task_requirements(ctx)
    if not reqs:
        return None
    clickables = state.clickables
    if not clickables:
        return None
    for req_type, req_value in reqs:
        match = find_matching_option(clickables, req_type, req_value)
        if match:
            return {'kind': 'force_action', 'action': 'click[' + match + ']', 'message': 'Select required ' + req_type + ' before purchasing'}
    return None
